// Domains that link to competitors but not to you, most competitors first.
const s = $('Settings').first().json;
const norm = (d) => String(d || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const own = norm(s.yourDomain);
const minComp = Math.max(1, Number(s.minCompetitors) || 1);
const minRank = Number(s.minRankPassed) || 0;
const maxSpam = s.maxSpamScore === '' || s.maxSpamScore == null ? 100 : Number(s.maxSpamScore);
const yours = new Set($('Your referring domains').all().map((i) => i.json)
  .filter((r) => r.found !== false && r.referringDomain).map((r) => norm(r.referringDomain)));
const gap = new Map();
for (const { json: r } of $input.all()) {
  if (r.found === false || !r.referringDomain || r.isLost) continue;
  const d = norm(r.referringDomain);
  if (d === own || yours.has(d) || (r.spamScore ?? 0) > maxSpam) continue;
  const e = gap.get(d) ?? { competitors: new Set(), rank: 0, backlinks: 0, dofollow: 0 };
  e.competitors.add(norm(r.target));
  e.rank = Math.max(e.rank, r.rankPassed ?? 0);
  e.backlinks += r.backlinks ?? 0;
  e.dofollow += r.dofollowBacklinks ?? 0;
  gap.set(d, e);
}
const date = new Date().toISOString().slice(0, 10);
return [...gap.entries()]
  .filter(([, e]) => e.competitors.size >= minComp && e.rank >= minRank)
  .sort(([, a], [, b]) => b.competitors.size - a.competitors.size || b.rank - a.rank)
  .map(([d, e]) => ({ json: {
    date, referringDomain: d, linksToCompetitors: e.competitors.size, competitors: [...e.competitors].join(', '),
    bestRankPassed: e.rank, backlinksToCompetitors: e.backlinks, dofollowBacklinks: e.dofollow,
    yourDomain: own, yourDomainsRead: yours.size,
  } }));
